SELECT id, email, dept_id, manager_id, salary, hire_date, level, ROW_NUMBER() OVER (PARTITION BY dept_id ORDER BY hire_date DESC, id) AS row_seq, PERCENT_RANK() OVER (PARTITION BY level, dept_id ORDER BY salary DESC) AS salary_percent_rank, SUM(salary) OVER (PARTITION BY job_title ORDER BY salary, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_salary FROM employees
